public static function qty( $product_id ) {
	$v = get_post_meta( (int) $product_id, self::META, true );
	if ( '' === $v || null === $v ) { return null; }
	return max( 0, (int) $v );
}

/** Ar AV turi bent nurodytą kiekį. */
public static function has( $product_id, $need = 1 ) {
	$q = self::qty( $product_id );
	return ( null !== $q && $q >= (int) $need );
}

/** Sumažina AV likutį. Grąžina naują reikšmę arba WP_Error. */
public static function decrease( $product_id, $by, $priezastis = '' ) {
	$by = (int) $by;
	if ( $by <= 0 ) { return new WP_Error( 'blogas_kiekis', 'Kiekis turi būti teigiamas' ); }
	$q = self::qty( $product_id );
	if ( null === $q ) { return new WP_Error( 'nera_av', 'Prekė neturi AV likučio' ); }
	if ( $q < $by ) { return new WP_Error( 'nepakanka', "AV turi $q, prašoma $by" ); }
	$naujas = $q - $by;
	self::apsaugotas_rasymas( $product_id, $naujas );
	self::log( $product_id, $q, $naujas, $priezastis );
	return $naujas;
}

/** Padidina AV likutį (papildymas). */
public static function increase( $product_id, $by, $priezastis = '' ) {
	$by = (int) $by;
	if ( $by <= 0 ) { return new WP_Error( 'blogas_kiekis', 'Kiekis turi būti teigiamas' ); }
	$q = self::qty( $product_id );
	$naujas = ( null === $q ? 0 : $q ) + $by;
	self::apsaugotas_rasymas( $product_id, $naujas );
	self::log( $product_id, $q, $naujas, $priezastis );
	return $naujas;
}

